<main class="home-shell">
<div class="gallery-titlebar"><span>Bryce roots. A world of rendering tools.</span><span>Made by the community</span></div>
<nav class="software-nav" aria-label="Software galleries"><a href="<?= e(gallery_url($state, ['software' => '', 'page' => 1])) ?>" <?= !$state['software'] ? 'aria-current="page"' : '' ?>>All software</a><?php foreach (SOFTWARE as $id => $name): ?><a href="<?= e(gallery_url($state, ['software' => $id, 'page' => 1])) ?>" <?= $state['software'] === $id ? 'aria-current="page"' : '' ?>><?= e($name) ?></a><?php endforeach; ?></nav>
<div class="gallery-shell"><aside class="sidebar"><section class="sidebar-panel"><h2>Your community space</h2><div class="sidebar-body"><p>Share your artwork, discover new worlds and connect with other artists.</p><?php if ($user): ?><p>Signed in as <strong><?= e($user['username']) ?></strong></p><a href="/account">Your uploads →</a><a href="/upload">Upload artwork +</a><?php else: ?><a href="/login">Sign in →</a><a href="/register">Create an account →</a><?php endif; ?><a href="/about">About the community</a><p>Upload artwork, save favorites and build your collection.</p></div></section><section class="sidebar-panel"><h2>Gallery categories</h2><nav aria-label="Categories"><a href="<?= e(gallery_url($state, ['category' => '', 'page' => 1])) ?>">All artwork <span><?= number_format(count($data['items'])) ?></span></a><?php foreach (listed_categories($data['categories']) as $c): ?><a href="<?= e(gallery_url($state, ['category' => (string)$c['id'], 'page' => 1])) ?>"><?= e($c['name']) ?><span><?= number_format(count(array_filter($data['items'], fn ($i) => (int)$i['categoryId'] === (int)$c['id']))) ?></span></a><?php endforeach; ?></nav></section></aside>
<section class="gallery-section" id="gallery"><div class="section-heading"><div><p class="eyebrow">THE RENDERING COMMUNITY</p><h1><?= $state['artist'] !== '' ? 'Artwork by ' . e($state['artist']) : 'Image gallery' ?></h1><p><?= e(site_settings()['description']) ?></p></div></div>
<form method="get" action="/#gallery" class="gallery-controls" id="gallery-filters"><?php if ($state['artist'] !== ''): ?><input type="hidden" name="artist" value="<?= e($state['artist']) ?>"><?php endif; ?>
<label class="select-wrap"><span class="sr-only">Software</span><select name="software" aria-label="Software"><option value="">All software</option><?php foreach (SOFTWARE as $id => $name): ?><option value="<?= e($id) ?>" <?= $state['software'] === $id ? 'selected' : '' ?>><?= e($name) ?></option><?php endforeach; ?></select></label>
<label class="search-box"><input type="search" name="q" value="<?= e($state['q']) ?>" aria-label="Search artworks" placeholder="Search the collection"></label>
<label class="select-wrap"><select name="category" aria-label="Category"><option value="">All categories</option><?php foreach (listed_categories($data['categories'], $state['category']) as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $state['category'] === (string)$c['id'] ? 'selected' : '' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label>
<label class="select-wrap"><select name="sort" aria-label="Sort artworks"><?php foreach (['recent' => 'Recently added', 'popular' => 'Most viewed', 'rated' => 'Archived rating'] as $id => $label): ?><option value="<?= $id ?>" <?= $state['sort'] === $id ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
<label class="select-wrap page-size-select">Images per page <select name="perPage"><?php foreach ([24, 48, 96] as $size): ?><option <?= $size === $state['perPage'] ? 'selected' : '' ?>><?= $size ?></option><?php endforeach; ?></select></label>
<button type="submit" id="apply-filters">Apply filters</button>
</form><p id="filter-status" class="filter-status" role="status" aria-live="polite"></p>
<div id="gallery-results"><?php require __DIR__ . '/results.php'; ?></div>
</section></div></main>
